import logging

import torch
import triton
import triton.language as tl

from flag_gems.runtime import torch_device_fn
from flag_gems.utils.random_utils import (
    philox_backend_seed_offset,
    uint_to_uniform_float,
)
from flag_gems.utils.shape_utils import volume

from .uniform import _mix32, use_fast_rng

_MAX_GRID_X = 65535  # device grid-dimension limit (Ascend coreDim <= 65535)


logger = logging.getLogger(__name__)


@triton.jit
def _mad(a, b, c):
    """Multiply-add.

    Written as ``a * b + c`` rather than ``tl.fma``: the backend lowers both to
    the same two vector instructions, and the measured times of a fill are
    identical either way, so the portable form is used.  (A Horner step
    therefore costs two vector ops on this target, which is why the
    polynomials below are kept as short as the error budget allows.)
    """
    return a * b + c


@triton.jit
def _sin_cos_pi(x):
    """sin/cos for an angle already reduced to [-pi, pi].

    The angle is built directly inside the principal interval, so no range
    reduction is needed at all (the device ``sin``/``cos`` do a full range
    reduction and ask for 272 KB of on-chip buffer, more than the 192 KB this
    target has).  A 4+1 term Horner chain per function keeps the error under
    2.4e-5 (sin) / 8.3e-5 (cos) over [-pi, pi], four orders of magnitude below
    the sampling noise of the distribution these feed.
    """
    x2 = x * x
    sin_x = x * _mad(
        _mad(
            _mad(_mad(2.19767311e-06, x2, -0.000193686972), x2, 0.00831615169),
            x2,
            -0.166642699,
        ),
        x2,
        0.999992171,
    )
    cos_x = _mad(
        _mad(
            _mad(_mad(1.87756032e-05, x2, -0.00133820223), x2, 0.0414830131),
            x2,
            -0.499744345,
        ),
        x2,
        0.999916607,
    )
    return sin_x, cos_x


@triton.jit
def _normal_pair_from_hashes(h0, h1, scale, mean):
    """Box-Muller on two counter hashes, scaled and shifted in the last FMA.

    The hash's low 23 bits become the mantissa of a float ``m`` in [1, 2), the
    standard trick for turning a counter into a uniform: ``u = m - 1``.  The
    angle needs no separate ``m - 1`` step -- ``(m - 1) * 2*pi - pi`` is folded
    into ``m * 2*pi - 3*pi``, which still lands in [-pi, pi) -- and the radius
    uses ``u0 = m0 - 1`` directly.

    The radius hash forces bit 0 of the mantissa, so ``u0`` never reaches 0
    (the smallest value is 2**-23) and no clamp is needed; the price is one bit
    of granularity, i.e. a uniform on [2**-23, 1) with steps of 2**-22.
    """
    u0 = (((h0 & 0x007FFFFE) | 0x3F800001).to(tl.float32, bitcast=True)) - 1.0
    m1 = ((h1 & 0x007FFFFF) | 0x3F800000).to(tl.float32, bitcast=True)

    theta = _mad(m1, 6.283185307179586, -9.42477796076938)
    r = tl.sqrt(scale * tl.log(u0))
    sin_t, cos_t = _sin_cos_pi(theta)
    return _mad(r, cos_t, mean), _mad(r, sin_t, mean)


@triton.jit
def _normal_pair_from_uniforms(u0, u1, std, mean):
    """Box-Muller on two plain uniforms in [0, 1) (non-hashed RNG path)."""
    u0 = tl.maximum(1.0e-7, u0)
    theta = _mad(u1, 6.283185307179586, -3.141592653589793)
    r = tl.sqrt(std * std * -2.0 * tl.log(u0))
    sin_t, cos_t = _sin_cos_pi(theta)
    return _mad(r, cos_t, mean), _mad(r, sin_t, mean)


@triton.jit
def _philox_pair(philox_seed, philox_offset, off):
    """Two independent uniforms in [0, 1) from ``tl.philox``."""
    seed64 = philox_seed.to(tl.int64)
    offset64 = philox_offset.to(tl.int64)
    c0 = (offset64 & 0xFFFFFFFF).to(tl.uint32)
    c1 = ((offset64 >> 32) & 0xFFFFFFFF).to(tl.uint32)
    c0 += off.to(tl.uint32) * 2
    _O = c0 * 0
    r0, r1, _O2, _O3 = tl.philox(seed64, c0, c1, _O, _O)
    return uint_to_uniform_float(r0), uint_to_uniform_float(r1)


@triton.jit(do_not_specialize=["philox_seed", "philox_offset"])
def _normal_fused_kernel(
    out_ptr,
    N,
    philox_seed,
    philox_offset,
    mean,
    std,
    BLOCK: tl.constexpr = 4096,
    UNROLL: tl.constexpr = 4,
    FAST_RNG: tl.constexpr = False,
):
    # Single-pass normal_functional: draw the standard-normal sample and apply
    # the affine (val * std + mean) transform in the same kernel, so out-of-place
    # normal costs one launch instead of a randn launch + a separate
    # pointwise-transform launch + a second full read/write of the buffer.
    pid = tl.program_id(0)
    # Grid-stride loop: the launch grid is capped (see _MAX_GRID_X).  Each
    # unrolled step produces one Box-Muller pair, i.e. ``2 * BLOCK`` elements,
    # and stores it before drawing the next one: keeping only two samples live
    # at a time is what lets the tile stay inside the 192 KB on-chip buffer
    # (holding four streams instead overflows it and costs ~13x).
    step = tl.num_programs(0) * BLOCK * UNROLL * 2
    base = pid * BLOCK * UNROLL * 2
    # (std**2 * -2) is folded into the radius, so the final transform is a
    # single multiply-add per sample instead of three separate steps.
    scale = std * std * -2.0
    if FAST_RNG:
        key = philox_seed.to(tl.uint32) ^ (philox_offset.to(tl.uint32) * 0x1E3779B1)
        while base < N:
            for u in tl.static_range(UNROLL):
                off_0 = base + u * (BLOCK * 2) + tl.arange(0, BLOCK)
                off_1 = off_0 + BLOCK
                c = off_0.to(tl.uint32) * 2 + key
                n0, n1 = _normal_pair_from_hashes(_mix32(c), _mix32(c + 1), scale, mean)
                tl.store(
                    out_ptr + off_0,
                    n0,
                    mask=off_0 < N,
                    eviction_policy="evict_first",
                )
                tl.store(
                    out_ptr + off_1,
                    n1,
                    mask=off_1 < N,
                    eviction_policy="evict_first",
                )
            base += step
    else:
        while base < N:
            for u in tl.static_range(UNROLL):
                off_0 = base + u * (BLOCK * 2) + tl.arange(0, BLOCK)
                off_1 = off_0 + BLOCK
                u0, u1 = _philox_pair(philox_seed, philox_offset, off_0)
                n0, n1 = _normal_pair_from_uniforms(u0, u1, std, mean)
                tl.store(
                    out_ptr + off_0,
                    n0,
                    mask=off_0 < N,
                    eviction_policy="evict_first",
                )
                tl.store(
                    out_ptr + off_1,
                    n1,
                    mask=off_1 < N,
                    eviction_policy="evict_first",
                )
            base += step


def _vector_core_count(device):
    """Number of vector cores (0 when the query is unavailable).

    Only the launch geometry uses it: it decides how much work counts as "more
    than a few waves" and therefore how wide a tile pays off.
    """
    try:
        from triton.runtime import driver

        index = device.index if device.index is not None else 0
        props = driver.active.utils.get_device_properties(index)
        cores = props.get("num_vectorcore", 0) if isinstance(props, dict) else 0
        return int(cores) if cores else 0
    except Exception:
        return 0


def _launch_geometry(N, cores):
    """``(BLOCK, UNROLL)`` for a fill of ``N`` elements.

    ``BLOCK`` is the number of Box-Muller pairs a lane block holds, so one
    program covers ``2 * BLOCK * UNROLL`` elements.  Wide blocks (4096 pairs is
    the widest that still fits the 192 KB on-chip buffer with the compiler's
    multi-buffering) pay off only when there are several waves of work; a fill
    of a few thousand elements is launch-bound, and there a *few* mid-sized
    programs beat both one wide program and many tiny ones: the per-program
    prologue dominates once the tile is small (measured on a 64x64 bf16 fill:
    2.4 us at 4 programs of 1024 elements, 3.0 us at 16 programs, 7.1 us at 64).
    """
    if cores <= 0:
        cores = 40
    if N >= 4096 * 2 * cores * 4:
        return 4096, 4
    if N >= 4096 * 2 * cores:
        return 4096, 1
    return 512, 1


def normal_functional(self, mean=0.0, std=1.0, *, generator=None):
    logger.debug("GEMS NORMAL_FUNCTIONAL")
    shape = self.shape
    device = self.device

    # Out-of-place sibling of normal_: draw standard-normal samples with the
    # counter-based RNG and apply the affine (val * std + mean) transform in a
    # single fused kernel — one launch, one write pass, instead of a randn launch
    # followed by a separate pointwise transform that re-reads and re-writes
    # the whole buffer.
    out = torch.empty(shape, device=device, dtype=self.dtype)
    N = volume(shape)
    if N == 0:
        # Nothing to draw, and a zero-element grid would be rejected by the
        # device (coreDim must be non-zero).
        return out
    block, unroll = _launch_geometry(N, _vector_core_count(device))

    def grid_fn(meta):
        return (min(triton.cdiv(N, meta["BLOCK"] * meta["UNROLL"] * 2), _MAX_GRID_X),)

    # A pair consumes two counters per element offset, and a tail tile can round
    # the consumed range past N; reserve that rounded-up range so consecutive
    # launches never re-draw the same counters.
    increment = 2 * N + 4 * block * unroll
    philox_seed, philox_offset = philox_backend_seed_offset(
        increment, generator=generator
    )
    with torch_device_fn.device(device):
        _normal_fused_kernel.run(
            out,
            N,
            philox_seed,
            philox_offset,
            mean,
            std,
            BLOCK=block,
            UNROLL=unroll,
            FAST_RNG=use_fast_rng(),
            grid=grid_fn,
            warmup=False,
        )

    return out
